module tb;
    logic clk = 0;
    logic rst_n = 1;
    logic enable = 0;
    logic [7:0] count;

    counter dut (.*);

    always #5 clk = ~clk;

    initial begin
        $display("Testing counter...");

        // Reset
        rst_n = 0;
        #10;
        rst_n = 1;

        // Test 1: Count with enable
        enable = 1;
        repeat(5) @(posedge clk);
        if (count !== 5) $display("ERROR: Expected 5, got %0d", count);
        else $display("PASS: Count = %0d", count);

        // Test 2: Disable
        enable = 0;
        @(posedge clk);
        if (count !== 5) $display("ERROR: Should stay at 5, got %0d", count);
        else $display("PASS: Count stayed at 5");

        // Test 3: Reset
        rst_n = 0;
        @(posedge clk);
        if (count !== 0) $display("ERROR: Should reset to 0, got %0d", count);
        else $display("PASS: Reset to 0");

        $display("Test completed");
        $finish;
    end
endmodule

